sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 lightPos;
uniform float brightness;
uniform float ghosts;
uniform float ghostSpacing;
uniform float ghostSize;
uniform float haloRadius;
uniform float haloWidth;
uniform float rays;
uniform float rayLength;
uniform float rayRot;
layout(color) uniform half4 tint;
uniform float chromatic;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float3 hsv2rgb(float3 c) {
    float3 p = abs(fract(float3(c.x) + float3(1.0, 0.6666667, 0.3333333)) * 6.0 - 3.0);
    return c.z * mix(float3(1.0), saturate(p - 1.0), c.y);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 uv = coord / size;
    float asp = size.x / size.y;
    float2 toL = (uv - lightPos) * float2(asp, 1.0);
    float dL = length(toL);
    float3 tn = float3(tint.rgb);
    float3 flare = tn * exp(-dL * dL * 60.0);
    float ang = atan(toL.y, toL.x) + radians(rayRot);
    float rayM = pow(abs(cos(ang * rays * 0.5)), 8.0) * exp(-dL / max(rayLength * 0.5, 0.01));
    flare += tn * rayM * 0.5 * step(0.5, rays);
    float2 axisEnd = float2(1.0) - lightPos;
    for (int i = 0; i < 8; i++) {
        if (float(i) >= ghosts) break;
        float t = (float(i) + 1.0) / (ghosts + 1.0) * ghostSpacing * 1.6;
        float2 g = mix(lightPos, axisEnd, t);
        float dg = length((uv - g) * float2(asp, 1.0));
        float rr = ghostSize * (0.6 + hash21(float2(float(i), 3.0)));
        float disc = 1.0 - smoothstep(rr * 0.7, rr, dg);
        float3 gc = hsv2rgb(float3(fract(0.08 * float(i) + chromatic * 0.5), 0.5, 1.0));
        flare += gc * disc * 0.25;
    }
    float3 ring = float3(exp(-pow((dL - haloRadius * (1.0 + chromatic * 0.05)) / haloWidth, 2.0)), exp(-pow((dL - haloRadius) / haloWidth, 2.0)), exp(-pow((dL - haloRadius * (1.0 - chromatic * 0.05)) / haloWidth, 2.0)));
    flare += ring * tn * 0.4;
    float3 o = s + flare * brightness;
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
